var EXTRA=[{"dot": "gray", "j": "Knee", "h": "Dopo protesi totale con robot ROSA il fenotipo CPAK cambia spesso, senza peggiorare gli esiti a breve", "v": "Coorte retrospettiva di un solo chirurgo: il fenotipo è stimato da radiografie corte e non da radiografie lunghe, e il controllo è breve.", "pmid": "42914595", "doi": "10.1016/j.knee.2026.104654", "temi": ["protesi totale", "CPAK", "allineamento", "robot"]}, {"dot": "gray", "j": "Knee", "h": "Protesi totale mediale stabilizzata contro conservazione del crociato: nessuna differenza di flessione prevista", "v": "Studio retrospettivo esplorativo con un modello predittivo costruito sul gruppo con conservazione del crociato; il gruppo mediale stabilizzato è piccolo e il modello ha una capacità predittiva solo moderata.", "pmid": "42913046", "doi": "10.1016/j.knee.2026.104657", "temi": ["protesi totale", "flessione", "mediale stabilizzata"]}, {"dot": "gray", "j": "Int J Sports Phys Ther", "h": "Ritorno allo sport dopo LCA: gli strumenti psicologici esistono, ma non c'è consenso su quali usare", "v": "Scoping review: la dimensione psicologica entra in modo incoerente nelle decisioni di rientro; la lacuna segnalata è la mancanza di consenso sugli strumenti.", "pmid": "42893311", "doi": "10.26603/001c.171296", "temi": ["LCA", "ritorno allo sport", "psicologia", "rientro"]}, {"dot": "gray", "j": "Healthcare (Basel)", "h": "Tendinopatia rotulea negli atleti: revisione narrativa, senza criteri diagnostici condivisi", "v": "Gli autori ricordano che manca una linea guida e che i reperti di imaging sono frequenti anche negli asintomatici, con rischio di sovradiagnosi; è una revisione narrativa.", "pmid": "42881687", "doi": "10.3390/healthcare14193248", "temi": ["tendine rotuleo", "atleti", "diagnosi", "sport"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Prelievo rotuleo per il LCA: riempire i difetti con osso e residuo del legamento, nota tecnica con video", "v": "Nota tecnica senza pazienti né esiti: descrive la preferenza degli autori per ridurre il dolore nel sito di prelievo; riguarda l'innesto rotuleo, non il quadricipitale.", "pmid": "42910140", "doi": "10.1002/atn2.70318", "temi": ["innesto rotuleo", "LCA", "sito di prelievo"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Osteotomia tibiale alta con emipiatto mediale per un piatto tibiale consolidato in varo", "v": "Nota tecnica con guida e impianto su misura stampati in tre dimensioni per la malunione post-traumatica; nessuna casistica.", "pmid": "42909272", "doi": "10.1002/atn2.70329", "temi": ["osteotomia", "piatto tibiale", "malunione", "guida su misura"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "LCA all-inside: un metodo per misurare la lunghezza intra-articolare dell'innesto e dimensionare i tunnel ciechi", "v": "Nota tecnica senza esiti: propone una misura individuale per evitare il disallineamento fra innesto e tunnel; nessun paziente riportato nell'abstract.", "pmid": "42903403", "doi": "10.1002/atn2.70284", "temi": ["LCA", "all-inside", "tunnel", "misurazione"]}, {"dot": "gray", "j": "Cureus", "h": "Lussazione rotulea in un quindicenne: frammento osteocondrale incarcerato, letto all'inizio come proveniente dal condilo", "v": "Case report: il frammento proveniva dalla faccetta rotulea mediale; ricorda di cercare lesioni osteocondrali dopo una lussazione, ma è un solo caso.", "pmid": "42903861", "doi": "10.7759/cureus.116564", "temi": ["rotula", "lussazione", "osteocondrale", "adolescente"]}, {"dot": "gray", "j": "Musculoskelet Sci Pract", "h": "Dolore anteriore di ginocchio nei giovani: i criteri di selezione degli studi variano molto", "v": "Scoping review: per ogni condizione sono usati moltissimi criteri diversi, e senza criteri comuni gli studi sono difficili da confrontare.", "pmid": "42880203", "doi": "10.1016/j.msksp.2026.103668", "temi": ["dolore anteriore", "giovani", "Osgood-Schlatter", "tendinopatia"]}, {"dot": "gray", "j": "Med Sci Sports Exerc", "h": "Calciatrici d'élite ritirate: il ginocchio è la sede chirurgica più frequente, soprattutto per i legamenti", "v": "Studio trasversale su questionario anonimo: descrive la frequenza delle sedi operate, non le cause; il LCA guida gli interventi al ginocchio.", "pmid": "42900791", "doi": "10.1249/MSS.0000000000004196", "temi": ["calcio femminile", "LCA", "chirurgia", "lungo termine"]}, {"dot": "gray", "j": "J Robot Surg", "h": "Chirurgia robotica in Germania: l'artrosi del ginocchio sale al secondo posto fra le diagnosi", "v": "Serie storica descrittiva di dati ospedalieri aggregati: i casi con codice robotico crescono ogni anno, ma i dati non riportano esiti clinici.", "pmid": "42900265", "doi": "10.1007/s11701-026-04084-z", "temi": ["robot", "protesi", "artrosi", "Germania"]}];
var SCOPERTE=[{"t": "Embolizzazione dell'arteria genicolare per l'artrosi: il registro tedesco misura l'adozione, non il sollievo dal dolore", "v": "Radiologia interventistica (Cardiovasc Intervent Radiol, registro DeGIR, Charité): più di duemila procedure in oltre cento centri in due anni, con successo tecnico dichiarato dai centri e poche complicanze, ma il registro non è fatto per sorvegliarle e non misura il dolore. Vale la deviazione perché è una terapia che i pazienti con artrosi possono chiederti; è un dato di diffusione, non di efficacia.", "pmid": "42897320", "doi": "10.1007/s00270-026-04657-3", "temi": ["embolizzazione", "artrosi", "radiologia interventistica", "registro"]}, {"t": "Il calcio volante del Tai Chi agonistico: dove cade il carico sul ginocchio d'appoggio", "v": "Biomeccanica di uno sport orientale (Front Bioeng Biotechnol, laboratorio di ingegneria dello sport della Cina): in dieci atleti un modello a elementi finiti mette il picco di sollecitazione all'atterraggio nel LCA e nella parte anteriore dei menischi. Vale la deviazione perché porta il ginocchio in una disciplina che non conosci; è un modello su dieci atleti, non un dato di rischio.", "pmid": "42909104", "doi": "10.3389/fbioe.2026.1959458", "temi": ["Tai Chi", "biomeccanica", "elementi finiti", "LCA"]}, {"t": "Risonanza a basso campo per il ginocchio: utile per menisco e legamenti, meno per la cartilagine iniziale", "v": "Imaging e intelligenza artificiale (J Magn Reson Imaging, University College Dublin): una revisione sistematica di trentuno studi trova buone prestazioni per le lesioni meniscali e legamentose e minore sensibilità per la degenerazione cartilaginea precoce; la ricostruzione con IA migliora l'immagine, ma in pochi studi monocentrici legati a un produttore. Vale la deviazione perché è l'imaging fuori dai grandi ospedali; la prova è eterogenea.", "pmid": "42920104", "doi": "10.1002/jmri.70597", "temi": ["risonanza", "basso campo", "intelligenza artificiale", "imaging"]}];
var SOC={"1": {"video": "Rottura della radice del menisco: si può sospettare già alla visita? Uno studio di Lima su 201 pazienti ha provato un segno clinico, detto di Akmese.\n\nIl segno ha riconosciuto la maggior parte delle rotture della radice posteriore del menisco interno e ha dato pochi falsi allarmi.\n\nIl limite: i pazienti erano già destinati all'artroscopia e le rotture erano 28, poche per essere sicuri. Non sostituisce la risonanza.\nFonte: PubMed, PMID 42901444.", "linkedin": "Segno di Akmese e radice meniscale posteriore mediale: sensibilità 85,7% (IC 95% 68,5-94,3, calcolo mio) e specificità 98,8% (IC 95% 95,9-99,7, calcolo mio) in 201 pazienti (Rev Esp Cir Ortop Traumatol, 2026).\n\nIl limite: popolazione già selezionata per l'artroscopia, 28 radici rotte, quattro non riconosciute; non sostituisce la RM.\nFonte: PubMed, PMID 42901444.", "instagram": "Radice del menisco: un segno alla visita\n\nUno studio su 201 pazienti: il segno di Akmese ha riconosciuto la maggior parte delle rotture della radice.\n\nPazienti già destinati all'artroscopia; non sostituisce la risonanza.\nFonte: PubMed, PMID 42901444.", "pazienti": "Rottura della radice del menisco: un segno durante la visita può insospettire il medico. Uno studio su 201 persone ha provato il segno di Akmese, che ha riconosciuto la maggior parte delle rotture e ha dato pochi falsi allarmi.\n\nNon sostituisce la risonanza: riguarda persone già destinate all'artroscopia.\nFonte: PubMed, PMID 42901444."}};
var SOCV={"1": {"video": {"chir": ["Segno di Akmese per la rottura della radice posteriore del menisco mediale: studio diagnostico prospettico di Lima su 201 pazienti già in lista per artroscopia, con l'artroscopia come riferimento.", "Ventotto radici rotte. Sensibilità 85,7% (IC 95% 68,5-94,3, calcolo mio), specificità 98,8% (IC 95% 95,9-99,7, calcolo mio), LR+ 74,1 e LR− 0,15; quattro rotture non riconosciute e due falsi positivi.", "Limiti: popolazione già selezionata per la chirurgia, prevalenza del 14% che non è quella dell'ambulatorio, confronto con la RM non riportato nell'abstract. Segno aggiuntivo per il sospetto, non sostituisce RM né artroscopia.\nFonte: PubMed, PMID 42901444."], "misto": ["Rottura della radice del menisco interno: si può sospettare già durante la visita? Uno studio di Lima su 201 pazienti destinati all'artroscopia ha provato un segno clinico, chiamato segno di Akmese.", "Il segno ha riconosciuto 24 delle 28 rotture della radice e ha dato solo due falsi allarmi su 173 pazienti senza rottura (calcolo nostro dai dati riportati).", "Il limite: i pazienti erano già stati selezionati per l'intervento e le rotture erano poche, quindi il risultato non vale in automatico per ogni visita. Il segno non sostituisce la risonanza.\nFonte: PubMed, PMID 42901444."], "pazienti": ["Rottura della radice del menisco: un segno durante la visita può far sospettare il problema. Uno studio di Lima su 201 persone ha provato il segno di Akmese.", "Il segno ha riconosciuto la maggior parte delle rotture e ha dato pochissimi falsi allarmi.", "Serve solo a insospettire il medico: la diagnosi si conferma con la risonanza e con l'artroscopia, e lo studio riguarda persone già destinate all'intervento.\nFonte: PubMed, PMID 42901444."]}, "linkedin": {"chir": ["Segno di Akmese e radice posteriore del menisco mediale (Rev Esp Cir Ortop Traumatol, 2026): coorte prospettica di 201 pazienti già in lista per artroscopia, 28 radici rotte.", "Sensibilità 85,7% (IC 95% 68,5-94,3, calcolo mio), specificità 98,8% (IC 95% 95,9-99,7, calcolo mio), VPP 92,3%, VPN 97,7%, LR+ 74,1, LR− 0,15; kappa dell'affidabilità non riportato nell'abstract.", "Il limite: spettro chirurgico selezionato, quattro falsi negativi, nessun confronto con la RM nell'abstract.\nFonte: PubMed, PMID 42901444."], "misto": ["Rottura della radice del menisco interno: un segno clinico per sospettarla prima della risonanza. Studio prospettico di Lima su 201 pazienti destinati all'artroscopia.", "Il segno di Akmese ha riconosciuto 24 delle 28 rotture e ha dato due falsi positivi (calcolo nostro dai dati riportati); gli autori lo propongono come aiuto al sospetto, non come sostituto della risonanza.", "Il limite: pazienti già selezionati per l'intervento e poche rotture.\nFonte: PubMed, PMID 42901444."], "pazienti": ["Rottura della radice del menisco: un segno durante la visita può aiutare il medico a sospettarla. Studio su 201 persone.", "Il segno di Akmese ha riconosciuto la maggior parte delle rotture e ha dato pochi falsi allarmi.", "Non sostituisce la risonanza ed è stato provato su persone già destinate all'artroscopia.\nFonte: PubMed, PMID 42901444."]}, "instagram": {"chir": ["Segno di Akmese e radice meniscale", "201 pazienti: sensibilità 85,7% (IC 95% 68,5-94,3, calcolo mio), specificità 98,8%. Rotture della radice 28.", "Spettro chirurgico selezionato; non sostituisce la RM.\nFonte: PubMed, PMID 42901444."], "misto": ["Radice del menisco: un segno alla visita", "In 201 pazienti destinati all'artroscopia il segno di Akmese ha riconosciuto 24 rotture su 28 della radice, con pochi falsi allarmi.", "Pazienti già selezionati e rotture poche; non sostituisce la risonanza.\nFonte: PubMed, PMID 42901444."], "pazienti": ["Menisco: un segno alla visita", "Uno studio su 201 persone: il segno di Akmese ha riconosciuto la maggior parte delle rotture della radice del menisco.", "Non sostituisce la risonanza, che resta l'esame di conferma.\nFonte: PubMed, PMID 42901444."]}, "reel": {"chir": ["[Testo a schermo] Segno di Akmese: sensibilità 85,7%", "201 pazienti; specificità 98,8%.", "IC 95% sensibilità 68,5-94,3 (calcolo mio); solo 28 rotture.\nFonte: PubMed, PMID 42901444."], "misto": ["[Testo a schermo] Radice del menisco: un segno alla visita", "201 pazienti destinati all'artroscopia.", "24 rotture su 28 riconosciute; non sostituisce la risonanza.\nFonte: PubMed, PMID 42901444."], "pazienti": ["[Testo a schermo] Menisco: un segno alla visita", "Studio su 201 persone.", "Insospettisce il medico; la conferma è la risonanza.\nFonte: PubMed, PMID 42901444."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #Menisco #Ginocchio", "instagram": "#ortopedia #ginocchio #menisco #radicemeniscale #visitaortopedica #chirurgiadelginocchio #medicinabasatasulleprove #ortopediaticino #ticino #salute", "kw": "menisco, radice meniscale, rottura del menisco, visita del ginocchio, ginocchio, ortopedia"}};
var NLB={"1": {"prof": ["Radice mediale rotta: segno di Akmese con sensibilità 86% e specificità 99% in 201 casi", "Studio diagnostico prospettico (Rev Esp Cir Ortop Traumatol, 2026; Lima, 201 pazienti già in lista per artroscopia): con l'artroscopia come riferimento, 28 radici posteriori mediali rotte; sensibilità 85,7% (IC 95% 68,5-94,3, calcolo mio), specificità 98,8% (IC 95% 95,9-99,7, calcolo mio), LR+ 74,1, LR− 0,15.", "Nota critica: popolazione già selezionata per la chirurgia, 28 casi positivi, quattro rotture non riconosciute, nessun confronto con la RM nell'abstract; non sostituisce RM né artroscopia."], "mix": ["Rottura della radice del menisco: un segno all'esame clinico può aiutare a sospettarla", "In uno studio prospettico di Lima su 201 pazienti già destinati all'artroscopia, un segno clinico detto di Akmese ha riconosciuto 24 delle 28 rotture della radice posteriore del menisco interno e ha dato pochissimi falsi allarmi (2 su 173 senza rottura; calcolo nostro dai dati riportati).", "Nota sul limite: i pazienti erano già stati selezionati per l'intervento e le rotture erano poche, quindi il risultato non si applica in modo automatico a ogni visita; il segno non sostituisce la risonanza."], "paz": ["Rottura della radice del menisco: un segno durante la visita può far sospettare il problema", "Un gruppo di medici di Lima ha provato un segno da cercare durante la visita del ginocchio, chiamato segno di Akmese, in 201 persone che dovevano comunque fare l'artroscopia. Il segno ha riconosciuto la maggior parte delle rotture della radice del menisco interno e ha dato pochi falsi allarmi.", "Nota rassicurante: serve solo a insospettire il medico. La diagnosi si conferma con la risonanza e con l'artroscopia, e lo studio riguarda persone già destinate all'intervento."], "kw": "menisco, radice meniscale, rottura del menisco, visita del ginocchio"}, "2": {"prof": ["UKA mediale: punteggi simili in tutte le classi di BMI e nessun reintervento in 1483 pazienti", "Coorte retrospettiva monocentrica (Zhonghua Yi Xue Za Zhi, 2026; Shijiazhuang, 1483 UKA mediali, controllo medio 33,9 mesi): KSS, OKS e VAS migliorano in tutte e quattro le classi di BMI (p<0,001) senza differenze fra classi (p>0,05); nessun reintervento, anche nei 51 con BMI ≥35.", "Nota critica: retrospettivo, controllo di circa tre anni, solo 51 pazienti con BMI ≥35 (con zero eventi il limite superiore del tasso è circa 5,9%), nessun confronto con altre protesi."], "mix": ["Protesi parziale del ginocchio: esiti simili anche nelle persone con peso corporeo elevato", "In un grande centro cinese, 1483 persone con una protesi che sostituisce solo la parte interna del ginocchio sono state divise per indice di massa corporea. A circa tre anni dall'intervento dolore e funzione erano migliorati in tutti i gruppi, senza differenze fra gruppi, e nessuno ha avuto bisogno di una nuova operazione.", "Nota sul limite: lo studio è retrospettivo, segue i pazienti per circa tre anni e include solo 51 persone con indice molto alto, un campione piccolo per escludere eventi rari."], "paz": ["Protesi parziale del ginocchio: buoni risultati a breve termine anche con peso più alto", "Un centro cinese ha seguito per circa tre anni 1483 persone con una protesi che sostituisce solo una parte del ginocchio, divise in gruppi per peso corporeo. In tutti i gruppi dolore e funzione sono migliorati e nessuno ha dovuto essere operato di nuovo.", "Nota rassicurante: sono risultati a pochi anni e i gruppi con peso molto alto erano piccoli; la scelta della protesi si discute con il chirurgo, caso per caso."], "kw": "protesi parziale ginocchio, protesi monocompartimentale, artrosi ginocchio, peso corporeo"}, "3": {"prof": ["Linea articolare: MPTA e LDFA pesano uguale, e l'orizzontale spesso non è raggiungibile", "Modello matematico bidimensionale (KSSTA, 2026; Montreal; 36 configurazioni): da appoggio bipodalico a monopodalico la linea articolare scende di 2,6°; ogni grado di MPTA o LDFA la sposta di 0,54° e 0,46°. Solo alcune configurazioni danno una linea orizzontale senza spostare il centro di massa.", "Nota critica: nessun paziente, nessun esito, livello V; il lavoro non dimostra che una linea orizzontale sia l'obiettivo giusto."], "mix": ["Allineamento del ginocchio: femore e tibia contano in egual misura nell'inclinazione", "Un gruppo di Montreal ha costruito un modello al computer dell'arto inferiore per capire come l'angolo del femore e quello della tibia determinino l'inclinazione dell'articolazione rispetto al suolo. Ogni grado in più dell'uno o dell'altro la inclina di circa mezzo grado, e in appoggio su una gamba l'inclinazione cala di quasi tre gradi.", "Nota sul limite: è un modello senza pazienti e non dimostra che un'articolazione orizzontale sia l'obiettivo giusto per ogni persona."], "paz": ["Ginocchio e allineamento: un modello al computer sull'inclinazione dell'articolazione", "Ricercatori di Montreal hanno usato un modello al computer per studiare come la forma delle ossa della coscia e della gamba inclini l'articolazione del ginocchio. Il risultato aiuta a capire la geometria del ginocchio, soprattutto quando si pianifica una correzione dell'asse.", "Nota rassicurante: è uno studio teorico, senza pazienti, e non cambia le cure attuali."], "kw": "allineamento ginocchio, osteotomia, asse della gamba, ginocchio varo"}, "4": {"prof": ["MPFL con tendine quadricipitale in osteogenesi imperfetta: un caso a tre anni senza recidiva", "Case report (Acta Orthop Traumatol Turc, 2026; Ankara): ragazzo di 15 anni con osteogenesi imperfetta di tipo V e lussazioni rotulee recidivanti, trattato con MPFL mininvasivo con lembo peduncolato di tendine quadricipitale senza tunnel rotulei. A tre anni dolore ridotto e funzione migliorata; nessuna frattura, cedimento o recidiva.", "Nota critica: un solo paziente, nessun punteggio standardizzato nell'abstract; è un'idea tecnica, non una prova."], "mix": ["Rotula instabile e ossa fragili: un caso trattato senza forare la rotula", "A un quindicenne con osteogenesi imperfetta, malattia che rende le ossa fragili, e lussazioni ripetute della rotula è stato ricostruito il legamento che la trattiene usando un lembo del tendine del quadricipite, senza forare la rotula. A tre anni il dolore era ridotto, la funzione migliorata e non c'erano state fratture né nuove lussazioni.", "Nota sul limite: è la storia di un solo paziente, che non permette di stimare i rischi né di generalizzare."], "paz": ["Rotula che si lussa in un ragazzo con ossa fragili: un intervento che evita di forare la rotula", "In un ragazzo di 15 anni con una malattia delle ossa fragili e lussazioni ripetute della rotula, il legamento è stato ricostruito con un lembo di tendine, senza forare la rotula per non indebolirla. Dopo tre anni stava meglio e non aveva avuto nuove lussazioni.", "Nota rassicurante: è il racconto di un singolo caso; ogni situazione va valutata dal chirurgo ortopedico, caso per caso."], "kw": "rotula, lussazione della rotula, MPFL, adolescenti"}, "5": {"prof": ["Inibizione muscolare artrogena del quadricipite: revisione per chirurghi, classificazione SANTI", "Revisione narrativa (Orthop Res Rev, 2026; Michigan State): AMI in oltre metà delle rotture acute del LCA e in circa un terzo dei pazienti nelle prime fasi dopo protesi totale; nessun gold standard, grado al letto del paziente con la classificazione SANTI; stimolazione elettrica neuromuscolare con l'evidenza più solida dopo LCA.", "Nota critica: revisione narrativa senza esiti propri, dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract."], "mix": ["Quadricipite che «non risponde» dopo crociato o protesi: come si riconosce e si tratta", "Una revisione per chirurghi descrive l'inibizione muscolare artrogena, un blocco riflesso del muscolo davanti alla coscia dopo un trauma o un intervento al ginocchio. È frequente dopo le rotture del crociato e dopo la protesi totale, e la stimolazione elettrica del muscolo è il trattamento con le prove più solide.", "Nota sul limite: è una revisione narrativa, quindi sintetizza gli studi senza misurare l'effetto di un trattamento."], "paz": ["Muscolo della coscia che fatica a riattivarsi dopo un trauma o un intervento al ginocchio", "Dopo una lesione del legamento crociato o una protesi, il muscolo davanti alla coscia può faticare a contrarsi anche se l'intervento è riuscito: è un blocco del sistema nervoso, riconoscibile con la visita. Una revisione indica che la stimolazione elettrica del muscolo e gli esercizi mirati aiutano.", "Nota rassicurante: è una condizione conosciuta e si tratta con la riabilitazione; il programma si decide con il medico e il fisioterapista."], "kw": "quadricipite, riabilitazione crociato, riabilitazione protesi ginocchio, debolezza muscolare"}, "6": {"prof": ["Resiniferatossina nell'artrosi: fase 3 su 469 pazienti, nessun vantaggio sul placebo", "RCT di fase 3 in doppio cieco (Osteoarthritis Cartilage, 2026; 469 pazienti, 52 settimane): WOMAC dolore a 12 settimane −2,96 con RTX-GRT7039 e −2,85 con placebo, differenza −0,11 (IC 95% da −0,50 a 0,27; p=0,569). Eventi avversi 62,8% contro 48,3%.", "Nota critica: l'intervallo esclude un vantaggio superiore a mezzo punto su 10; entrambi i bracci hanno ricevuto ropivacaina e cura standard."], "mix": ["Artrosi del ginocchio: un'infiltrazione sperimentale contro il dolore non ha battuto il placebo", "In uno studio internazionale su 469 persone con artrosi dolorosa del ginocchio, un'infiltrazione sperimentale non ha ridotto il dolore più del placebo, né a tre né a sei né a dodici mesi. Con il farmaco sono stati più frequenti gli effetti indesiderati, soprattutto il dolore al momento dell'iniezione.", "Nota sul limite: lo studio riguarda un solo dosaggio e un solo prodotto; il dolore è migliorato anche con il placebo, segno di quanto pesino il contesto e le cure di base."], "paz": ["Artrosi del ginocchio: un'infiltrazione sperimentale non ha dato più sollievo del placebo", "Uno studio su 469 persone con artrosi del ginocchio ha confrontato un'infiltrazione sperimentale con un placebo. Il dolore è diminuito in entrambi i gruppi, senza differenze fra i due, e con il farmaco sono stati più frequenti gli effetti indesiderati.", "Nota rassicurante: è un prodotto non in uso corrente; le terapie abituali dell'artrosi non cambiano per questo studio."], "kw": "artrosi del ginocchio, infiltrazione ginocchio, dolore al ginocchio, studio clinico"}, "7": {"prof": ["PRP nell'artrosi del ginocchio: metanalisi di 12 RCT, effetti strutturali limitati e incostanti", "Metanalisi di RCT (Arch Orthop Trauma Surg, 2026; 12 studi, 1200 pazienti): cartilagine femororotulea SMD 0,94 (IC 95% 0,53-1,34), edema osseo SMD −0,40 (IC 95% da −0,71 a −0,09); nessuna differenza per cartilagine tibiale mediale, difetti, osteofiti, cisti; sinovite SMD −0,22 (IC 95% da −0,43 a 0,00).", "Nota critica: esiti di imaging e non clinici, eterogeneità non riportata nell'abstract; nessuna prova di effetto modificante la malattia."], "mix": ["Plasma ricco di piastrine nell'artrosi del ginocchio: che cosa cambia sulle immagini", "Una revisione di 12 studi randomizzati su 1200 persone ha cercato nelle immagini di risonanza gli effetti del plasma ricco di piastrine sull'artrosi del ginocchio. Gli effetti sono stati piccoli e non costanti: qualche segno sulla cartilagine dietro la rotula e sull'edema osseo, nessuno sulla cartilagine interna del ginocchio.", "Nota sul limite: le immagini non sono i sintomi, e gli autori stessi non vedono prova che il trattamento modifichi la malattia."], "paz": ["Plasma ricco di piastrine per l'artrosi del ginocchio: che cosa mostrano le immagini", "Una revisione di 12 studi su 1200 persone ha guardato se il plasma ricco di piastrine cambi l'aspetto del ginocchio artrosico alla risonanza. Gli effetti sono stati piccoli e non uniformi, e non c'è prova che fermi l'artrosi.", "Nota rassicurante: lo studio guarda le immagini e non il dolore; l'uso del trattamento si discute con il medico."], "kw": "PRP ginocchio, artrosi del ginocchio, plasma ricco di piastrine, cartilagine"}, "8": {"prof": ["Menisco laterale ipermobile: punteggio RM dei fascicoli con AUC 0,794 e sensibilità 58,5%", "Studio retrospettivo appaiato (Knee Surg Relat Res, 2026; Ansan; 53 ginocchia con HLM e 53 controlli): la distanza menisco-popliteo non differisce; il punteggio combinato dei fascicoli è l'unico indipendente (OR 0,098; IC 95% 0,034-0,257), AUC 0,794 (IC 95% 0,709-0,879), soglia ≤1,0, specificità 86,8%.", "Nota critica: coorte chirurgica selezionata, sensibilità modesta, nessuna validazione esterna; non esclude l'ipermobilità né sostituisce la valutazione artroscopica."], "mix": ["Menisco esterno ipermobile: che cosa può mostrare la risonanza e che cosa no", "In uno studio coreano su 106 ginocchia, la risonanza ha riconosciuto l'ipermobilità del menisco esterno soprattutto guardando i piccoli fasci che lo trattengono, più che misurando le distanze. Il metodo è abbastanza specifico, ma lascia sfuggire circa quattro casi su dieci.", "Nota sul limite: lo studio è retrospettivo, su pazienti già operati, e gli autori stessi precisano che la conferma resta l'esame in artroscopia."], "paz": ["Menisco esterno instabile: la risonanza può dare un indizio, la conferma viene dall'artroscopia", "Uno studio coreano ha cercato nella risonanza i segni di un menisco esterno troppo mobile, causa possibile di dolore e scatti. Alcuni segni nei piccoli legamenti attorno al menisco aiutano a sospettarlo, ma non bastano per escluderlo.", "Nota rassicurante: la risonanza è un indizio; la diagnosi sicura si fa con la visita e, se serve, con l'artroscopia."], "kw": "menisco esterno, menisco laterale, scatti al ginocchio, risonanza ginocchio"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"Rev Esp Cir Ortop Traumatol",h:"Radice posteriore del menisco mediale rotta: un segno clinico, quello di Akmese, la riconosce all'esame?",v:"Studio diagnostico di coorte prospettica (Lima): 201 pazienti di 18-55 anni, già in lista per artroscopia con diagnosi clinica di lesione del menisco mediale; con l'artroscopia come riferimento la radice posteriore era rotta in 28. Il segno di Akmese è risultato positivo in 26: sensibilità 85,7% (IC 95% 68,5-94,3, calcolo mio), specificità 98,8% (IC 95% 95,9-99,7, calcolo mio), LR+ 74,1 e LR− 0,15. Popolazione chirurgica selezionata: non dice quanto valga in ambulatorio.",ax:"Paucar-Vergara, Urdanivia-Martos, Toro-Huamanchumo",date:"ott 2026",meta:"studio diagnostico di coorte prospettica, 201 pazienti, riferimento artroscopico",pmid:'42901444',doi:'10.1016/j.recot.2026.10.010',journal:"Revista espanola de cirugia ortopedica y traumatologia",authors:"Paucar-Vergara SM, Urdanivia-Martos JS, Toro-Huamanchumo CJ",design:"Studio diagnostico di coorte prospettica in strutture sanitarie peruviane: pazienti di 18-55 anni programmati per artroscopia dopo una diagnosi clinica di lesione del menisco mediale (gennaio 2022-luglio 2023). Il segno di Akmese, descritto nell'abstract solo come ricerca di dolore o dolorabilità all'esame, è confrontato con l'artroscopia (sensibilità, specificità, valori predittivi, rapporti di verosimiglianza); affidabilità fra osservatori con il kappa. Solo abstract.",pop:"201 pazienti, età media 38,4 ± 9,8 anni; radice posteriore mediale rotta in 28 (14%, calcolo mio). Numero di centri, sesso e chi ha eseguito il segno non riportati nell'abstract.",results:"Segno positivo in 26 su 201; rottura confermata in 28. Sensibilità 85,7%, specificità 98,8%, VPP 92,3%, VPN 97,7%, LR+ 74,1, LR− 0,15. Dai valori riportati la tabella è 24 veri positivi, 4 falsi negativi, 2 falsi positivi e 171 veri negativi (calcolo mio): sensibilità IC 95% 68,5-94,3 e specificità IC 95% 95,9-99,7 (Wilson, calcolo mio). Affidabilità fra osservatori «molto buona» secondo gli autori; valore del kappa e intervalli degli autori non riportati nell'abstract.",concl:"Gli autori: in questa popolazione chirurgica selezionata il segno ha mostrato buona prestazione diagnostica e ottima affidabilità fra osservatori; può servire come strumento clinico aggiuntivo per il sospetto preoperatorio, la rilettura mirata della RM e la pianificazione, ma non sostituisce la RM né l'artroscopia.",limits:"Solo pazienti già selezionati per l'artroscopia: la prevalenza (14%) e lo spettro non sono quelli di un ambulatorio, e i valori predittivi non si trasferiscono · Solo 28 radici rotte: la sensibilità può scendere fino a circa 69% e quattro rotture sono sfuggite · Cecità del lettore rispetto all'artroscopia, confronto con la RM e numero di esaminatori non riportati nell'abstract.",perte:"Verde: tocca la tua rifissazione transtibiale della radice. Non cambia la tecnica: dice che un segno clinico potrebbe far sospettare la rottura prima della RM, ma in una popolazione già avviata alla chirurgia e con soli 28 casi. Cosa fare: puoi usarlo come domanda in più nel dolore mediale posteriore e, se positivo, rivedere la radice sulla RM; non sostituisce la RM."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Zhonghua Yi Xue Za Zhi",h:"Protesi monocompartimentale mediale: risultati simili a ogni classe di BMI e nessun reintervento",v:"Coorte retrospettiva monocentrica (Shijiazhuang): 1483 UKA mediali, controllo medio 33,9 ± 5,3 mesi, in quattro classi di BMI (317, 790, 325 e 51 pazienti). KSS, OKS e VAS migliorano in tutte le classi (p<0,001) e non differiscono fra classi (p>0,05), neppure FJS o la quota di miglioramento; nessun reintervento in nessun gruppo. Nei 51 con BMI ≥35 il tasso reale di reintervento può arrivare al 5,9% (regola del tre).",ax:"Liu, Ji, Wang, Zhou, Li, Liu",date:"ott 2026",meta:"coorte retrospettiva monocentrica, 1483 UKA mediali, controllo medio 33,9 mesi",pmid:'42907212',doi:'10.3760/cma.j.cn112137-20251230-03480',journal:"Zhonghua yi xue za zhi",authors:"Liu DH, Ji G, Wang X, Zhou HC, Li GM, Liu GB",design:"Coorte retrospettiva monocentrica (Knee Joint Center, First Hospital of Hebei Medical University): UKA mediale 2021-2023, pazienti divisi in quattro classi di BMI (<25, 25-<30, 30-<35, ≥35 kg/m²). Esito primario l'incidenza di reintervento; secondari KSS, OKS, VAS e Forgotten Joint Score. Confronto dei punteggi prima e dopo entro ogni classe e fra classi. Solo abstract; tecnica, impianto e uso del robot non riportati.",pop:"1483 pazienti, età media 63,0 ± 6,5 anni, rapporto maschi:femmine 1:3,72; 317 con BMI <25, 790 con 25-<30, 325 con 30-<35 e 51 con ≥35. Il gruppo ≥35 è più giovane (58,9 ± 6,3 contro 64,3 ± 6,9 anni, p<0,001).",results:"Dopo l'intervento KSS clinico, KSS funzionale, OKS e VAS migliorano in tutte le classi (tutti p<0,001). Fra le classi nessuna differenza nei punteggi finali (KSS clinico, KSS funzionale, OKS, VAS, FJS; tutti p>0,05) né nella quota di miglioramento. Reinterventi: 0 su 1483. Valori dei punteggi e intervalli di confidenza non riportati nell'abstract; per 0 su 51 con BMI ≥35 il limite superiore è circa 5,9% (regola del tre, calcolo mio).",concl:"Gli autori: la UKA mediale migliora in modo significativo esiti clinici e funzionali in tutte le classi di BMI, e chi ha BMI ≥35 ottiene risultati a breve-medio termine paragonabili a chi ha BMI più basso.",limits:"Retrospettivo e monocentrico, controllo medio di circa tre anni: i reinterventi tardivi non si vedono · Solo 51 pazienti con BMI ≥35 e zero eventi: l'assenza di reinterventi non esclude un tasso fino a circa 5,9% · Nessun confronto con altre protesi e nessun dato su tecnica, impianto o robot nell'abstract.",perte:"Verde: tocca la tua monocompartimentale. Dice che a circa tre anni il BMI alto non peggiora punteggi né reinterventi, ma con pochi pazienti al di sopra di 35 e senza confronto con altre protesi. Cosa fare: il BMI da solo non esce da qui come ostacolo a breve-medio termine; la durata dell'impianto non è un dato di questo studio."},{n:3,mono:"m-kssta",dot:"green",sec:"res",j:"KSSTA",h:"Linea articolare: femore e tibia pesano uguale, e una linea orizzontale spesso non è raggiungibile",v:"Modello matematico bidimensionale (Montreal): 36 configurazioni con MPTA e LDFA variati in modo indipendente fra neutro e 7°. Passando dall'appoggio su due piedi a quello su uno la linea articolare scende di 2,6° in ogni configurazione; ogni grado di MPTA o di LDFA la sposta di circa 0,5° (0,54° e 0,46°). Solo un sottoinsieme delle configurazioni dà una linea orizzontale senza spostare il centro di massa. Nessun paziente, livello V.",ax:"Beckers, Hengartner, Lavigne, Kiss, Massé, Vendittoli",date:"ott 2026",meta:"modello matematico deterministico, 36 configurazioni anatomiche, nessun paziente, livello V",pmid:'42897439',doi:'10.1002/ksa.70653',journal:"Knee surgery, sports traumatology, arthroscopy : official journal of the ESSKA",authors:"Beckers G, Hengartner M, Lavigne M, Kiss MO, Massé V, Vendittoli PA",design:"Modello geometrico bidimensionale, deterministico e in forma chiusa, dell'arto inferiore con parametri antropometrici rappresentativi: MPTA e LDFA variati in modo indipendente da neutro a 7° in passi di 1° (36 configurazioni). Per ciascuna sono calcolati l'orientamento della linea articolare rispetto al suolo in appoggio bipodalico e monopodalico e lo spostamento teorico del centro di massa necessario per una linea orizzontale. Solo abstract.",pop:"Nessun paziente: parametri antropometrici rappresentativi; valori usati, sesso ed età non riportati nell'abstract.",results:"Dall'appoggio bipodalico al monopodalico la linea articolare scende di 2,6° in ogni configurazione. Per ogni grado di variazione dell'angolo la linea si sposta di 0,54° (MPTA) e 0,46° (LDFA). A pari allineamento anca-ginocchio-caviglia, MPTA e LDFA danno linee diverse. Solo un sottoinsieme limitato di configurazioni dà una linea orizzontale senza spostamento del centro di massa. Modello deterministico con risultati a 0,1° e 0,1 mm: intervalli di confidenza non riportati e non applicabili.",concl:"Gli autori: l'anatomia coronale di femore e tibia influenza in modo indipendente e prevedibile la linea articolare, e l'allineamento complessivo da solo non la predice; una linea orizzontale richiederebbe in molti casi un adattamento sostanziale del centro di massa. Se sia raggiungibile o sia l'obiettivo biomeccanico in tutti resta ignoto.",limits:"Nessun paziente e nessun esito: il modello non dice se una linea orizzontale serva a qualcosa · Geometria bidimensionale con parametri rappresentativi; tessuti molli e carico dinamico non compaiono nell'abstract · Il modello considera solo l'anatomia coronale entro 7° di varo-valgo.",perte:"Verde: tocca le tue osteotomie, perché la linea articolare entra nella pianificazione di una correzione. Non cambia nulla in sala: è un ordine di grandezza geometrico, non un risultato clinico. Cosa fare: se punti a una linea orizzontale, ricorda che questo lavoro non dimostra che sia l'obiettivo giusto."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Acta Orthop Traumatol Turc",h:"MPFL con tendine quadricipitale peduncolato in un adolescente con osteogenesi imperfetta: un caso a tre anni",v:"Case report (Ankara): ragazzo di 15 anni con osteogenesi imperfetta di tipo V e lussazione rotulea recidivante, trattato con ricostruzione mininvasiva del MPFL con un lembo peduncolato di tendine quadricipitale che risparmia la rotula, per evitare i tunnel rotulei su osso fragile. A tre anni dolore ridotto e funzione migliorata; nessuna frattura rotulea, cedimento della fissazione o recidiva. Un solo paziente.",ax:"Özel, Tokgöz",date:"set 2026",meta:"case report, 1 paziente di 15 anni, controllo a 3 anni",pmid:'42897817',doi:'10.5152/j.aott.2026.25829',journal:"Acta orthopaedica et traumatologica turcica",authors:"Özel T, Tokgöz MA",design:"Case report: ricostruzione mininvasiva del MPFL con lembo peduncolato di tendine quadricipitale, tecnica che risparmia la rotula (nessun tunnel rotuleo), scelta perché i tunnel rotulei delle tecniche standard possono aumentare il rischio di frattura rotulea in un osso fragile. Solo abstract.",pop:"1 paziente maschio di 15 anni con osteogenesi imperfetta di tipo V e lussazioni rotulee recidivanti.",results:"Un solo paziente: a 3 anni «marcato miglioramento clinico» con dolore ridotto e funzione migliorata; nessuna frattura rotulea, nessun cedimento della fissazione, nessuna instabilità recidivante. Punteggi, tipo di fissazione e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: la ricostruzione del MPFL che risparmia la rotula può essere un'opzione chirurgica sicura nell'instabilità rotulea in pazienti con osteogenesi imperfetta.",limits:"Un solo paziente: nessuna conclusione generalizzabile e nessuna stima di rischio · Nessun punteggio standardizzato né fissazione riportati nell'abstract · Malattia rara e popolazione diversa dalla casistica abituale.",perte:"Verde ma lontano: tocca il MPFL e il tendine quadricipitale, che sono anche tuoi, ma tu fissi con ancore FiberTak onlay e il paziente ha una malattia rara. Un caso non dimostra nulla: è un'idea tecnica per un osso fragile. Cosa fare: nessuna azione."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Orthop Res Rev",h:"Inibizione muscolare artrogena del quadricipite: una revisione per chirurghi, con la classificazione di Sonnery-Cottet",v:"Revisione narrativa (Michigan State): l'inibizione muscolare artrogena (AMI) compare in oltre la metà delle rotture acute del LCA e in circa un terzo dei pazienti nelle prime fasi dopo protesi totale. Nessun gold standard diagnostico; la classificazione SANTI di Sonnery-Cottet dà un grado al letto del paziente. Per la gestione la stimolazione elettrica neuromuscolare ha l'evidenza più solida (metanalisi di RCT dopo LCA), con inizio precoce associato a più forza recuperata. Nessun dato nuovo: sintesi.",ax:"Nolan, Bhatti, Operti, Ford, Kress, Jildeh",date:"ott 2026",meta:"revisione narrativa, nessun esito proprio",pmid:'42909948',doi:'10.2147/ORR.S643464',journal:"Orthopedic research and reviews",authors:"Nolan DL, Bhatti H, Operti N, Ford D, Kress DJ, Jildeh TR",design:"Revisione narrativa orientata al chirurgo in tre aree: neurofisiologia, valutazione clinica e diagnosi, gestione dell'AMI; con tabelle di evidenza graduata e un percorso clinico al letto del paziente proposto dagli autori. Strategia di ricerca e numero di studi non riportati nell'abstract. Solo abstract.",pop:"Nessuna popolazione propria: sintesi di letteratura su lesioni del LCA e protesi totale del ginocchio.",results:"Nessun risultato primario proprio. Frequenze citate: AMI in più della metà delle rotture acute del LCA e in circa un terzo dei pazienti nelle fasi iniziali dopo protesi totale. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: riconoscere precocemente l'AMI, soprattutto nelle finestre perioperatorie ad alto rischio, permette di distinguere l'inibizione neuromuscolare da un blocco meccanico, guidare il colloquio con il paziente e coordinare il trattamento prima che il recupero sia compromesso.",limits:"Revisione narrativa: nessuna ricerca sistematica dichiarata e nessun esito clinico proprio · Nessun gold standard diagnostico, quindi la frequenza dipende dalla definizione usata · Le misure quantitative (rapporto di attivazione centrale) sono riservate alla ricerca.",perte:"Verde: riguarda il post-operatorio del LCA e cita Sonnery-Cottet, un tuo riferimento; non tocca innesto né LET. Cosa fare: un deficit di estensione o di attivazione del quadricipite nelle prime settimane va distinto da un blocco meccanico; la stimolazione elettrica è la misura con più evidenza secondo la revisione."},{n:6,mono:"m-oac",dot:"gray",sec:"res",j:"Osteoarthritis Cartilage",h:"Resiniferatossina nel ginocchio artrosico: la fase 3 non batte il placebo sul dolore",v:"RCT di fase 3, in doppio cieco, 52 settimane: 469 pazienti con artrosi dolorosa randomizzati 1:1 a ropivacaina intra-articolare più RTX-GRT7039 (234) o placebo (235), con ripetizione alla settimana 26. WOMAC dolore (0-10) a 12 settimane: −2,96 contro −2,85, differenza −0,11 (IC 95% da −0,50 a 0,27; p=0,569). Eventi avversi 62,8% contro 48,3%; dolore da procedura 13,2% contro 3,9%.",ax:"Berenbaum, Latourte, Kivitz, Ivanavicius, Buller, Prasad, Eibl, Prevoo, Conaghan",date:"ott 2026",meta:"RCT di fase 3 in doppio cieco, 469 pazienti, 52 settimane",pmid:'42913877',doi:'10.1016/j.joca.2026.10.011',journal:"Osteoarthritis and cartilage",authors:"Berenbaum F, Latourte A, Kivitz A, Ivanavicius S, Buller S, Prasad N, Eibl C, Prevoo M, Conaghan PG",design:"RCT di fase 3, controllato con placebo, in doppio cieco, della durata di 52 settimane (NCT05248386): pazienti con artrosi del ginocchio dolorosa e radiografica, in cura standard, randomizzati 1:1 a ropivacaina 0,5% (5 mL) intra-articolare seguita da RTX-GRT7039 400 ng o placebo, ripetuti nel ginocchio indice alla settimana 26. Esito primario: variazione del WOMAC dolore (0-10) a 12 settimane. Solo abstract.",pop:"469 pazienti (234 RTX-GRT7039, 235 placebo); età, sesso e gravità radiografica non riportati nell'abstract.",results:"WOMAC dolore a 12 settimane: −2,96 (RTX-GRT7039) e −2,85 (placebo); differenza −0,11 (IC 95% da −0,50 a 0,27; p=0,569). Alle settimane 26 e 52: 0,03 (IC 95% da −0,38 a 0,44) e 0,14 (IC 95% da −0,35 a 0,63). Funzione e rigidità con andamento simile. Eventi avversi emergenti 259 (55,6%): 147 (62,8%) con il farmaco e 112 (48,3%) con il placebo; dolore da procedura 13,2% contro 3,9%.",concl:"Gli autori: RTX-GRT7039 intra-articolare non ha mostrato un beneficio clinicamente significativo né statisticamente significativo sul dolore rispetto al placebo; il profilo di sicurezza è coerente con gli studi precedenti.",limits:"Solo abstract: gravità radiografica, età e analisi per sottogruppi non riportate · Entrambi i bracci hanno ricevuto ropivacaina e cura standard: il calo di circa tre punti nel braccio placebo mostra quanto pesi il contesto · Un solo dosaggio testato.",perte:"Bianco: infiltrazione per l'artrosi, fuori dalla tua chirurgia. Utile come ordine di grandezza dell'effetto placebo (−2,85 punti su 10 a 12 settimane) e come studio informativo, non muto: l'intervallo esclude un vantaggio del farmaco oltre mezzo punto. Cosa fare: nessuna azione."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Arch Orthop Trauma Surg",h:"PRP nell'artrosi del ginocchio: gli effetti sulle immagini sono limitati e incostanti",v:"Metanalisi di 12 RCT (1200 pazienti) sugli esiti strutturali: spessore o volume della cartilagine femororotulea a favore del PRP (SMD 0,94; IC 95% 0,53-1,34), nessuna differenza per cartilagine tibiale mediale e progressione dei difetti; edema osseo ridotto (SMD −0,40; IC 95% da −0,71 a −0,09); sinovite non diversa (SMD −0,22; IC 95% da −0,43 a 0,00). Gli autori non vedono prova di un effetto modificante la malattia.",ax:"Pasqualotto, Pasqualotto, Lunelli, de Sousa, Funchal, Dos Reis",date:"ott 2026",meta:"metanalisi di 12 RCT, 1200 pazienti, esiti di imaging",pmid:'42918921',doi:'10.1007/s00402-026-06543-6',journal:"Archives of orthopaedic and trauma surgery",authors:"Pasqualotto E, Pasqualotto T, Lunelli L, de Sousa FB, Funchal LFZ, Dos Reis FB",design:"Revisione sistematica con metanalisi di RCT (PubMed, Embase, Cochrane fino a maggio 2026) sugli effetti strutturali del PRP nell'artrosi del ginocchio valutati con imaging; rischio relativo per gli esiti binari, differenze medie standardizzate o assolute per quelli continui, con IC 95%. Solo abstract.",pop:"12 RCT, 1200 pazienti; preparazioni di PRP, controlli, durata del controllo e rischio di bias non riportati nell'abstract.",results:"Cartilagine femororotulea (spessore/volume): SMD 0,94 (IC 95% 0,53-1,34). Nessuna differenza per cartilagine tibiale mediale e progressione dei difetti. Edema osseo (WORMS): SMD −0,40 (IC 95% da −0,71 a −0,09). Sinovite: SMD −0,22 (IC 95% da −0,43 a 0,00). Osteofiti e cisti subcondrali senza differenze. Eterogeneità non riportata nell'abstract.",concl:"Gli autori: il PRP ha effetti limitati e incostanti sugli esiti strutturali e non offre prova chiara di un'azione modificante la malattia; i risultati favorevoli su cartilagine femororotulea ed edema osseo vanno letti con cautela e servono altri RCT di qualità con endpoint di imaging standardizzati.",limits:"Eterogeneità dei preparati di PRP e degli endpoint di imaging non riportata nell'abstract · Gli esiti strutturali non sono esiti clinici: una variazione di imaging non dice nulla sul dolore · Il segno più forte (femororotulea) non si ripete negli altri compartimenti.",perte:"Bianco: artrosi non chirurgica, fuori dalla tua pratica. Serve a rispondere a chi chiede se il PRP «ricostruisca» la cartilagine: l'effetto su immagini è debole e incostante. Cosa fare: nessuna azione."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Knee Surg Relat Res",h:"Menisco laterale ipermobile: sulla RM conta il punteggio dei fascicoli popliteomeniscali, non la distanza",v:"Studio retrospettivo (Ansan, Corea): 53 ginocchia con menisco laterale ipermobile confermato in artroscopia e 53 controlli chirurgici appaiati. La distanza fra menisco laterale e tendine popliteo non differisce; il punteggio combinato dei fascicoli è l'unico indicatore indipendente: AUC 0,794 (IC 95% 0,709-0,879), soglia ≤1,0, sensibilità 58,5%, specificità 86,8%. Aiuta a sospettare, non a escludere.",ax:"Park, Park, Shim, Moon, Suh, Kim",date:"ott 2026",meta:"studio retrospettivo con appaiamento, 53 ginocchia con menisco laterale ipermobile e 53 controlli",pmid:'42920202',doi:'10.1186/s43019-026-00354-0',journal:"Knee surgery & related research",authors:"Park HJ, Park JH, Shim E, Moon SR, Suh DH, Kim JG",design:"Studio retrospettivo: ginocchia con RM seguita da valutazione artroscopica della stabilità del menisco laterale; dopo appaiamento per propensity score 53 ginocchia con menisco laterale ipermobile (HLM) confermato e 53 controlli chirurgici. Variabili RM: distanza menisco-popliteo, misura per regione d'interesse, rapporto di intensità del segnale, integrità dei fascicoli popliteomeniscali (PMF) con punteggio combinato; regressione logistica di Firth, curva ROC, indice di Youden. Solo abstract.",pop:"106 ginocchia (53 con HLM, 53 controlli chirurgici appaiati); età, sesso e indicazione all'artroscopia non riportati nell'abstract.",results:"Distanza menisco laterale-popliteo senza differenze. Rapporto di intensità del segnale sagittale: OR 1,067 (IC 95% 1,012-1,137; p=0,044). Punteggio combinato PMF: OR 0,098 (IC 95% 0,034-0,257; p<0,001), unico indipendente nell'analisi multivariata. Modello con solo PMF: AUC 0,794 (IC 95% 0,709-0,879); soglia ≤1,0, sensibilità 58,5%, specificità 86,8%, accuratezza 72,6%.",concl:"Gli autori: il punteggio PMF combinato è il marcatore RM più coerente con l'HLM confermato in artroscopia; può offrire un'informazione aggiuntiva che aumenta il sospetto, ma non esclude l'HLM né stabilisce la diagnosi, e la decisione di eseguire l'artroscopia non va basata sul solo punteggio; la valutazione dinamica artroscopica resta necessaria.",limits:"Retrospettivo e su una coorte chirurgica selezionata: il comportamento in un ginocchio non operato non è noto · Sensibilità modesta (58,5%): quasi quattro HLM su dieci passano inosservati · Lettori, validazione esterna e variabilità fra osservatori non riportati nell'abstract.",perte:"Bianco: nel perimetro, ma tocca il menisco laterale ipermobile, che non è fra le tue tecniche elencate. Cosa fare: nessuna azione; se un dolore laterale con scatti ha RM normale, il punteggio non basta a escludere."}];
var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Domenica 25 ottobre. Apro con la settimana, poi il giorno. Dalla settimana, quattro lavori che contano. Lunedì, a Pittsburgh, una coorte di milleduecentoventisei ricostruzioni del crociato dai quattordici anni: il reintervento per perdita di movimento è più frequente nelle donne, in particolare con innesto rotuleo e sutura del menisco laterale. Mercoledì, la radice posteriore del menisco laterale suturata per via transtibiale durante il crociato: con il tunnel tibiale condiviso l'operazione dura molto meno, senza differenza nel punteggio di Lysholm. Venerdì, la rifissazione della radice mediale con osteotomia: la sutura tiene nell'ottantanove per cento dei casi, ma l'estrusione del menisco cresce comunque. Sabato, la metanalisi sulla protesi monocompartimentale robotica: meno revisioni, ma ventisette studi su trentaquattro non randomizzati. Tensioni mosse nella settimana: la radice meniscale, due volte, sempre sull'estrusione; il rinforzo laterale solo con note di sfondo. Oggi otto lavori, nessuna scheda rossa e nessuna arancione. Nessun richiamo di dispositivi nuovo, nessuna linea guida o consensus nuovo sulla tua pratica e nessuna ritrattazione che ti riguardi. Il lavoro del giorno riguarda la tua radice meniscale: uno studio prospettico di Lima su duecentouno pazienti già destinati all'artroscopia ha provato il segno clinico di Akmese per la rottura della radice posteriore del menisco mediale. Il segno è risultato positivo in ventisei; le radici rotte erano ventotto. Sensibilità ottantacinque virgola sette per cento, intervallo di confidenza da sessantotto virgola cinque a novantaquattro virgola tre, specificità novantotto virgola otto per cento: intervalli calcolati da me sui dati riportati. Il limite: pazienti già selezionati per la chirurgia, ventotto rotture, quattro non riconosciute, nessun confronto con la risonanza nell'abstract. Può aiutare a sospettare, non sostituisce la risonanza. Ho letto solo l'abstract. Poi quattro lavori verdi. Una coorte retrospettiva di millequattrocentoottantatré protesi monocompartimentali mediali: punteggi simili in tutte le classi di indice di massa corporea e nessun reintervento, ma i pazienti con indice sopra trentacinque sono cinquantuno e il controllo è di circa tre anni. Un modello matematico sulla linea articolare: femore e tibia pesano in modo uguale, circa mezzo grado per ogni grado, e una linea orizzontale spesso non è raggiungibile; nessun paziente. Un caso di ricostruzione del legamento patellofemorale mediale con tendine quadricipitale peduncolato in un quindicenne con osteogenesi imperfetta, senza recidive a tre anni: un solo paziente. Una revisione narrativa sull'inibizione muscolare artrogena del quadricipite, con la classificazione di Sonnery-Cottet. Tre lavori bianchi. Una fase tre sulla resiniferatossina intra-articolare: nessun vantaggio sul placebo, differenza meno zero virgola undici, intervallo da meno zero virgola cinquanta a zero virgola ventisette. Una metanalisi di dodici studi randomizzati sul PRP: effetti strutturali limitati e incostanti. Uno studio coreano sulla risonanza del menisco laterale ipermobile, con sensibilità modesta. Tensioni: nessuna si è mossa oggi.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Domenica venticinque ottobre. Comincio dalla settimana: quattro lavori che contano."}, {"chi": "B", "t": "Quali?"}, {"chi": "A", "t": "A Pittsburgh il reintervento per perdita di movimento dopo il crociato è più frequente nelle donne, con innesto rotuleo e sutura del menisco laterale. Poi la radice laterale con tunnel tibiale condiviso, che accorcia molto l'operazione. Poi la radice mediale con osteotomia: la sutura tiene, ma l'estrusione cresce. E sabato la metanalisi sulla monocompartimentale robotica."}, {"chi": "B", "t": "E le tensioni?"}, {"chi": "A", "t": "La radice meniscale si è mossa due volte, sempre sull'estrusione. Il rinforzo laterale solo con note di sfondo. Oggi invece nessuna tensione si è mossa. Otto lavori, nessuna scheda rossa, nessuna arancione, nessun richiamo di dispositivi e nessuna ritrattazione."}, {"chi": "B", "t": "Qual è il lavoro del giorno?"}, {"chi": "A", "t": "Un segno clinico per la rottura della radice posteriore del menisco mediale, il segno di Akmese. Studio prospettico di Lima su duecentouno pazienti già destinati all'artroscopia."}, {"chi": "B", "t": "Quanto funziona?"}, {"chi": "A", "t": "Le radici rotte erano ventotto. Sensibilità ottantacinque virgola sette per cento, con intervallo da sessantotto virgola cinque a novantaquattro virgola tre, calcolato da me. Specificità novantotto virgola otto."}, {"chi": "B", "t": "Quindi per la mia rifissazione transtibiale?"}, {"chi": "A", "t": "Può servire come domanda in più davanti a un dolore mediale posteriore, per rivedere la radice sulla risonanza. Ma i pazienti erano già selezionati per l'intervento, quattro rotture sono sfuggite e non c'è il confronto con la risonanza. Ho letto solo l'abstract."}, {"chi": "B", "t": "E gli altri lavori verdi?"}, {"chi": "A", "t": "La monocompartimentale mediale dà risultati simili a ogni classe di indice di massa corporea e nessun reintervento, ma con pochi pazienti sopra trentacinque e tre anni di controllo. Poi un modello sulla linea articolare per le osteotomie, un caso di legamento patellofemorale mediale con tendine quadricipitale in un ragazzo con osteogenesi imperfetta, e una revisione sull'inibizione muscolare del quadricipite."}, {"chi": "B", "t": "Tra i bianchi?"}, {"chi": "A", "t": "La fase tre sulla resiniferatossina non batte il placebo, il PRP ha effetti limitati sulle immagini, e una risonanza sul menisco laterale ipermobile con sensibilità modesta."}];
